import java.io.IOException;
import java.util.*;

public class Test {
    int readInt() {
        int val = 0;
        boolean negFlag = false;
        try {
            boolean started = false;
            for (int ch = 0; (ch = System.in.read()) != -1; ) {
                if (ch == '-') {
                    started = true;
                    negFlag = true;
                    continue;
                } else if (ch >= '0' && ch <= '9') {
                    started = true;
                    val = val * 10 + ch - '0';
                } else if (started) break;
            }
        } catch (IOException e) {
        }
        return negFlag ? -val : val;
    }

    int R, C;
    Scanner scanner = new Scanner(System.in);
    long[][] pascal = new long[64][64];
    long minDist = Long.MAX_VALUE;

    void explorePaths(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (minDist <= 1 || diff - pascal[v1][R]*pascal[v2][R] >= minDist) return;
        if (v1 == R - 1 && v2 == R - 1) {
            if (diff < minDist) minDist = diff;
            return;
        }
        if (v1 >= R) {
            long deltaX = pascal[v1][R] - pascal[v1-1][R], deltaY = pascal[v2][R];
            explorePaths(x, y + deltaX*deltaY, v1 - 1, v2);
        }
        if (v2 >= R) {
            long deltaX = pascal[v1][R], deltaY = pascal[v2][R] - pascal[v2-1][R];
            explorePaths(x + deltaX*deltaY, y, v1, v2 - 1);
        }
    }

    int[] countA = new int[64], countB = new int[64];
    Map<Long, Long> cacheMap = new TreeMap<>();
    char[] sequenceChars;

    long computeSolution(long x, long y, int v1, int v2) {
        long key = x*10000 + v1*100 + v2;
        Long cachedVal = cacheMap.get(key);
        if (cachedVal != null) return cachedVal;
        long res = 0L;
        long d = Math.abs(x - y);
        if (d - pascal[v1][R]*pascal[v2][R] > minDist) {
            cacheMap.put(key, res);
            return res;
        }
        if (v1 < R || v2 < R) {
            int sumIdx = v1 + v2;
            if (v1 >= countA[sumIdx] && v2 >= countB[sumIdx]) {
                v1 -= countA[sumIdx];
                v2 -= countB[sumIdx];
                res = pascal[v1+v2][v1];
                cacheMap.put(key, res);
                return res;
            }
            cacheMap.put(key, res);
            return res;
        }
        char c = sequenceChars[v1 + v2 - 1];
        if (c != 'B') {
            long c1 = pascal[v1][R] - pascal[v1 - 1][R], s2 = pascal[v2][R];
            res += computeSolution(x, y + c1*s2, v1 - 1, v2);
        }
        if (c != 'A') {
            long s1 = pascal[v1][R], c2 = pascal[v2][R] - pascal[v2-1][R];
            res += computeSolution( x + s1*c2, y, v1, v2 - 1);
        }
        cacheMap.put(key, res);
        return res;
    }

    void run() {
        R = readInt(); C = readInt(); scanner.nextLine();
        sequenceChars = scanner.nextLine().toCharArray();
        for (int i = 0; i <= 2*(R + C); i++)
            for (int j = 0; j <= 2*(R + C); j++) {
                if (j == 0) pascal[i][j] = 1;
                else if (i == 0) pascal[i][j] = 0;
                else pascal[i][j] = pascal[i-1][j-1] + pascal[i-1][j];
            }
        int v1 = R + C, v2 = R + C;
        long xCoord = 0, yCoord = 0;
        while (v1 >= R && v2 >= R) {
            if (xCoord > yCoord) {
                long c1 = pascal[v1][R] - pascal[v1 - 1][R], s2 = pascal[v2][R];
                yCoord += c1 * s2;
                v1--;
            } else {
                long s1 = pascal[v1][R], c2 = pascal[v2][R] - pascal[v2-1][R];
                xCoord += s1 * c2;
                v2--;
            }
        }
        minDist = Math.abs(xCoord - yCoord);
        explorePaths(0, 0, R + C, R + C);
        for (int i = 0; i < 2*(R+C); i++) {
            countA[i + 1] = countA[i] + (sequenceChars[i] == 'A' ? 1 : 0);
            countB[i + 1] = countB[i] + (sequenceChars[i] == 'B' ? 1 : 0);
        }
        long answer = computeSolution(0, 0, R + C, R + C);
        System.out.println(answer);
    }

    public static void main(String[] args) {
        new Test().run();
    }
}
